// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed parameters: an address `from`, an array of one address `tos0` packed via bytes to allow fuzzing arrays,
    // and a uint value. We will reconstruct arrays of length 1 from the fuzz inputs so the deciding case _tos.length == 1
    // is reachable by the fuzzer.
    function testFuzz_property(address from, address tos0, uint256 v0) public {
        // Build arrays of length exactly 1 to target the boundary that the mutant changes.
        address[] memory tos = new address[](1);
        tos[0] = tos0;
        uint[] memory vals = new uint[](1);
        vals[0] = v0;

        // call transfer and observe whether it reverts or not by try/catch
        bool ok;
        try c.transfer(from, address(this), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: for ANY input where _tos.length > 0 (here length == 1), the reference implementation
        // returns (does not revert). The mutant with require(_tos.length > 1) will revert for length == 1.
        // Assert that the call did NOT revert (this holds on the reference for all such inputs; the mutant will fail
        // for some fuzzed inputs and thus this test will catch it).
        assertTrue(ok);
    }
}
